const payload = msg.payload || {};
const chatId = payload.chatId || payload.chatid || payload.message?.chat?.id;
const text = String(payload.content || payload.text || payload.message?.text || '').trim();

if (!chatId) {
    node.warn('Mensagem sem chatId recebida do Telegram.');
    return [null, null, null];
}

const sessionKey = `studentSession:${chatId}`;
const session = flow.get(sessionKey) || { status: 'needCpf' };

function direct(content) {
    return {
        payload: {
            chatId,
            type: 'message',
            content
        }
    };
}

function onlyDigits(value) {
    return String(value || '').replace(/\D/g, '');
}

function normalize(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase();
}

function isValidCpf(cpf) {
    cpf = onlyDigits(cpf);
    if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;

    let sum = 0;
    for (let i = 0; i < 9; i++) sum += Number(cpf[i]) * (10 - i);
    let check = 11 - (sum % 11);
    if (check >= 10) check = 0;
    if (check !== Number(cpf[9])) return false;

    sum = 0;
    for (let i = 0; i < 10; i++) sum += Number(cpf[i]) * (11 - i);
    check = 11 - (sum % 11);
    if (check >= 10) check = 0;
    return check === Number(cpf[10]);
}

function extractCpf(value) {
    const digits = onlyDigits(value);
    return digits.length === 11 ? digits : null;
}

function extractRm(value) {
    const match = String(value || '').match(/\bRM\s*[-:]?\s*([A-Za-z0-9]+)\b/i);
    if (!match) return null;
    return `RM${match[1]}`.toUpperCase();
}

function sqlQuote(value) {
    return String(value).replace(/'/g, "''");
}

function studentWhere(identifier) {
    if (identifier?.cpf) return `a.cpf = '${sqlQuote(identifier.cpf)}'`;
    if (identifier?.rm) return `upper(a.rm) = '${sqlQuote(identifier.rm.toUpperCase())}'`;
    if (identifier?.alunoId) return `a.id = ${Number(identifier.alunoId)}`;
    return null;
}

function baseStudentSelect(where) {
    return `SELECT a.id AS aluno_id, a.cpf, a.nome AS aluno_nome, a.rm, c.nome AS curso_nome FROM aluno a JOIN curso c ON c.id = a.curso_id WHERE ${where} LIMIT 1`;
}

function buildWatsonMessage() {
    const apiKey = env.get('WATSON_API_KEY');
    const assistantId = env.get('WATSON_ASSISTANT_ID');
    const serviceUrl = String(env.get('WATSON_SERVICE_URL') || '').replace(/\/$/, '');
    const version = env.get('WATSON_VERSION') || '2024-08-25';

    msg.chatId = chatId;
    msg.userText = text || '/start';
    msg.watsonConfigured = Boolean(apiKey && assistantId && serviceUrl);
    msg.fallbackReply = 'Em que posso ajudar';

    if (msg.watsonConfigured) {
        msg.method = 'POST';
        msg.url = `${serviceUrl}/v2/assistants/${assistantId}/message?version=${version}`;
        msg.headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'Authorization': `Basic ${Buffer.from(`apikey:${apiKey}`).toString('base64')}`
        };
        msg.payload = {
            input: {
                message_type: 'text',
                text: msg.userText
            },
            context: {
                global: {
                    system: {
                        user_id: String(chatId)
                    }
                }
            }
        };
    }

    return msg;
}

function menu(nome, rm) {
    const prefix = nome && rm ? `Aluno identificado: ${nome}\nRM: ${rm}\n\n` : '';
    return `${prefix}Agora voce pode consultar: curso, notas, materias inscritas, faltas e turnos.\n\nExemplos:\n- notas\n- curso\n- materias inscritas\n- faltas\n- turno\n\nTambem aceito outro CPF ou RM na pergunta, como: notas RM1002.`;
}

function buildQuery(queryType, identifier) {
    const where = studentWhere(identifier);
    if (!where) return null;

    const studentColumns = 'a.id AS aluno_id, a.cpf, a.nome AS aluno_nome, a.rm, c.nome AS curso_nome';

    if (queryType === 'identify' || queryType === 'profile' || queryType === 'curso' || queryType === 'rm') {
        return baseStudentSelect(where);
    }

    if (queryType === 'notas') {
        return `SELECT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas, n.cp_1, n.cp_2, n.gs_1, n.ch_1, n.media_final FROM aluno a JOIN curso c ON c.id = a.curso_id LEFT JOIN notas n ON n.aluno_id = a.id LEFT JOIN materia m ON m.id = n.materia_id WHERE ${where} ORDER BY m.nome`;
    }

    if (queryType === 'materias') {
        return `SELECT DISTINCT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN aluno_materia am ON am.aluno_id = a.id JOIN materia m ON m.id = am.materia_id WHERE ${where} ORDER BY m.nome`;
    }

    if (queryType === 'turnos') {
        return `SELECT DISTINCT ${studentColumns}, m.nome AS materia_nome, m.turno FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN aluno_materia am ON am.aluno_id = a.id JOIN materia m ON m.id = am.materia_id WHERE ${where} ORDER BY m.turno, m.nome`;
    }

    if (queryType === 'faltas') {
        return `SELECT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas, COUNT(am.data_presenca) AS presencas_registradas, max(m.total_horas - COUNT(am.data_presenca), 0) AS faltas_calculadas FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN materia m ON m.curso_id = a.curso_id LEFT JOIN aluno_materia am ON am.aluno_id = a.id AND am.materia_id = m.id WHERE ${where} GROUP BY a.id, m.id ORDER BY m.nome`;
    }

    return null;
}

function routeSql(queryType, identifier) {
    const topic = buildQuery(queryType, identifier);
    if (!topic) return null;
    msg.chatId = chatId;
    msg.queryType = queryType;
    msg.identifier = identifier;
    msg.topic = topic;
    return msg;
}

const normalized = normalize(text);

if (!text || normalized === '/start' || normalized === 'start' || normalized === 'iniciar') {
    flow.set(sessionKey, { status: 'needCpf' });
    return [null, null, direct('Ola. Para eu saber com quem estou falando, informe seu CPF.')];
}

if (['sair', 'reset', 'reiniciar', 'trocar aluno', 'trocar'].includes(normalized)) {
    flow.set(sessionKey, { status: 'needCpf' });
    return [null, null, direct('Tudo bem. Informe o CPF do aluno para iniciar novamente.')];
}

const cpf = extractCpf(text);
const rm = extractRm(text);

if (session.status !== 'identified') {
    if (!cpf) {
        return [null, null, direct('Para iniciar, informe o CPF do aluno com 11 digitos.')];
    }

    if (!isValidCpf(cpf)) {
        return [null, null, direct('CPF invalido. Confira os digitos e tente novamente.')];
    }

    return [routeSql('identify', { cpf }), null, null];
}

if (['ajuda', 'help', 'menu', 'opcoes', 'opções'].includes(normalized)) {
    return [null, null, direct(menu(session.nome, session.rm))];
}

const identifier = cpf ? { cpf } : rm ? { rm } : { alunoId: session.alunoId };

if (cpf && !isValidCpf(cpf)) {
    return [null, null, direct('CPF invalido. Confira os digitos e tente novamente.')];
}

let queryType = null;
if (/\b(rm|registro de matricula|matricula)\b/.test(normalized) && !/materia|disciplina/.test(normalized)) queryType = 'rm';
if (/\b(curso|graduacao|graduação)\b/.test(normalized)) queryType = 'curso';
if (/\b(nota|notas|media|média|cp|gs|ch)\b/.test(normalized)) queryType = 'notas';
if (/\b(materia|materias|matéria|matérias|disciplina|disciplinas|inscrita|inscritas|matriculada|matriculadas)\b/.test(normalized)) queryType = 'materias';
if (/\b(falta|faltas|ausencia|ausências|presenca|presenças|presença|presenças)\b/.test(normalized)) queryType = 'faltas';
if (/\b(turno|turnos|horario|horário|periodo|período)\b/.test(normalized)) queryType = 'turnos';

if (!queryType && (cpf || rm)) queryType = 'profile';

if (!queryType) {
    return [null, null, direct(menu(session.nome, session.rm))];
}

const sqlMsg = routeSql(queryType, identifier);
if (!sqlMsg) {
    return [null, buildWatsonMessage(), null];
}

return [sqlMsg, null, null];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const queryType = msg.queryType || 'profile';
const sessionKey = `studentSession:${msg.chatId}`;

function maskCpf(value) {
    const cpf = String(value || '').replace(/\D/g, '');
    return cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
}

function reply(content) {
    msg.payload = {
        chatId: msg.chatId,
        type: 'message',
        content
    };
    return msg;
}

function studentNotFound() {
    const id = msg.identifier?.cpf ? maskCpf(msg.identifier.cpf) : msg.identifier?.rm || 'informado';
    return reply(`Nao encontrei aluno para ${id}. Confira o CPF/RM e tente novamente.`);
}

function sessionFrom(row) {
    return {
        status: 'identified',
        alunoId: row.aluno_id,
        cpf: row.cpf,
        rm: row.rm,
        nome: row.aluno_nome,
        curso: row.curso_nome
    };
}

function header(row) {
    return [
        `Aluno: ${row.aluno_nome}`,
        `CPF: ${maskCpf(row.cpf)}`,
        `RM: ${row.rm}`,
        `Curso: ${row.curso_nome}`
    ];
}

if (rows.length === 0) {
    return studentNotFound();
}

const aluno = rows[0];

if (queryType === 'identify') {
    flow.set(sessionKey, sessionFrom(aluno));
    return reply([
        `Aluno identificado: ${aluno.aluno_nome}`,
        `RM: ${aluno.rm}`,
        '',
        'Agora voce pode consultar: curso, notas, materias inscritas, faltas e turnos.',
        'Voce tambem pode informar outro CPF ou RM na pergunta.'
    ].join('\n'));
}

if (queryType === 'profile') {
    return reply(header(aluno).join('\n'));
}

if (queryType === 'rm') {
    return reply([`RM de ${aluno.aluno_nome}: ${aluno.rm}`, `CPF: ${maskCpf(aluno.cpf)}`].join('\n'));
}

if (queryType === 'curso') {
    return reply([`Curso de ${aluno.aluno_nome}:`, aluno.curso_nome, `RM: ${aluno.rm}`].join('\n'));
}

if (queryType === 'notas') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) {
        return reply(`${aluno.aluno_nome} ainda nao possui notas cadastradas.`);
    }

    const lines = header(aluno).concat('', 'Notas:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: CP1 ${materia.cp_1}, CP2 ${materia.cp_2}, GS1 ${materia.gs_1}, CH1 ${materia.ch_1}, media ${materia.media_final}`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'materias') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) {
        return reply(`${aluno.aluno_nome} nao possui materias inscritas cadastradas.`);
    }

    const lines = header(aluno).concat('', 'Materias inscritas:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome} (${materia.turno}, ${materia.total_horas}h)`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'turnos') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) {
        return reply(`${aluno.aluno_nome} nao possui turnos cadastrados.`);
    }

    const lines = header(aluno).concat('', 'Turnos:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: ${materia.turno}`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'faltas') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) {
        return reply(`${aluno.aluno_nome} nao possui frequencia cadastrada.`);
    }

    const lines = header(aluno).concat('', 'Faltas:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: ${materia.faltas_calculadas} faltas calculadas, ${materia.presencas_registradas} presencas registradas`);
    }
    lines.push('', 'Obs.: no schema atual, faltas sao calculadas a partir da carga horaria menos presencas registradas.');
    return reply(lines.join('\n'));
}

return reply(header(aluno).join('\n'));

const generic = msg.payload?.output?.generic || [];
const texts = generic
    .filter(item => item.response_type === 'text' && item.text)
    .map(item => item.text.trim())
    .filter(Boolean);

let watsonText = texts.join('\n');
if (!watsonText || msg.statusCode >= 300) {
    watsonText = msg.fallbackReply || 'Em que posso ajudar';
}

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: `${watsonText}\n\nDigite seu CPF para consulta.`
};
return msg;

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: `${msg.fallbackReply || 'Em que posso ajudar'}\n\nDigite seu CPF para consulta.`
};
